const {chromium}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs');
(async()=>{const b=await chromium.launch({headless:true,executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH}),c=await b.newContext({viewport:{width:320,height:1000},permissions:['clipboard-read','clipboard-write'],reducedMotion:'reduce'}),p=await c.newPage(),out=process.env.OUTPUT_DIR,source=fs.readFileSync('/tmp/leetcode-719-frozen-6b5b115-20261025/leetcode/719/solution.py','utf8'),report={host:process.platform,labels:[],clipboard:[]};await p.goto(process.env.PREVIEW_URL);
for(const width of [320,390]){await p.setViewportSize({width,height:1000});for(const lang of ['en','zh']){await p.click(`[data-lang=${lang}]`);let longest={textWidth:-1};for(let i=0;i<7;i++){await p.selectOption('#preset',String(i));const r=await p.locator('#preset').evaluate(e=>{const s=getComputedStyle(e),ctx=document.createElement('canvas').getContext('2d');ctx.font=s.font;return {text:e.selectedOptions[0].text,textWidth:ctx.measureText(e.selectedOptions[0].text).width,available:e.clientWidth-parseFloat(s.paddingLeft)-parseFloat(s.paddingRight)-24};});assert.ok(r.textWidth<r.available);report.labels.push({width,lang,preset:i,...r});if(r.textWidth>longest.textWidth)longest={preset:i,...r};}await p.selectOption('#preset',String(longest.preset));await p.locator('#preset').screenshot({path:`${out}/${lang}-${width}-longest-native-select.png`});}}
for(const lang of ['en','zh']){await p.click(`[data-lang=${lang}]`);const sentinel=`719 ${lang} distinct native clipboard sentinel`;
await p.evaluate(async text=>{window.originalWrite=navigator.clipboard.writeText.bind(navigator.clipboard);await window.originalWrite(text);navigator.clipboard.writeText=async()=>{throw Error('forced denial');};},sentinel);
assert.equal(await p.evaluate(()=>navigator.clipboard.readText()),sentinel);
await p.click('#copy');assert.deepEqual(await p.locator('#copyText').evaluate(e=>({active:document.activeElement===e,start:e.selectionStart,end:e.selectionEnd,text:e.value})),{active:true,start:0,end:source.length,text:source});
assert.equal(await p.evaluate(()=>navigator.clipboard.readText()),sentinel);const shortcut=process.platform==='darwin'?'Meta+C':'Control+C';await p.keyboard.press(shortcut);assert.equal(await p.evaluate(()=>navigator.clipboard.readText()),source);report.clipboard.push({lang,sentinelVerifiedBeforeKey:true,shortcut,exactCharacters:source.length});await p.evaluate(()=>navigator.clipboard.writeText=window.originalWrite);}
await b.close();fs.writeFileSync(out+'/native-supplement.json',JSON.stringify(report,null,2)+'\n');console.log({labels:report.labels.length,clipboard:report.clipboard});})().catch(e=>{console.error(e);process.exit(1);});
